package com.aistock.market.comparison;
import java.time.*;import java.util.*;import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
import static com.aistock.market.comparison.ComparisonEvidenceRecords.*;
class ComparisonEvidenceOptionsTest {
 Evidence evidence(String stock,LocalDate from,LocalDate to){return new Evidence(UUID.randomUUID(),stock,UUID.randomUUID(),"a".repeat(64),"baostock","BACKWARD",from,to,"b".repeat(64),"c".repeat(64),"d".repeat(64),Instant.parse("2026-10-12T00:00:00Z"),List.of(),List.of());}
 @Test void newestShortWindowDoesNotHideCoveredYear(){var end=LocalDate.parse("2026-10-09");var shortVersion=evidence("SH600030",end.minusMonths(3),end);var year=evidence("SH600030",end.minusYears(1),end);var other=evidence("SH600276",end.minusYears(1),end);var result=ComparisonEvidenceOptions.select(List.of("SH600030","SH600276"),"1Y",Map.of("SH600030",List.of(shortVersion,year),"SH600276",List.of(other)),Map.of(),end);assertEquals(end,result.to());assertTrue(result.available());assertEquals(year.evidenceId(),result.stocks().get(0).evidenceId());}
 @Test void mixedCutoffsAndInsufficientCoverage(){var end=LocalDate.parse("2026-10-09");var result=ComparisonEvidenceOptions.select(List.of("SH600030","SH600276"),"1Y",Map.of("SH600030",List.of(evidence("SH600030",end.minusYears(1),end)),"SH600276",List.of(evidence("SH600276",end.minusMonths(3),end.minusDays(1)))),Map.of(),end);assertFalse(result.available());assertEquals(end.minusDays(1),result.to());assertEquals("INSUFFICIENT_COVERAGE",result.stocks().get(1).reason());}
 @Test void rejectsDuplicateUnknownPeriodAndMissingStock(){var end=LocalDate.parse("2026-10-09");assertThrows(RuntimeException.class,()->ComparisonEvidenceOptions.select(List.of("SH600030","SH600030"),"3M",Map.of(),Map.of(),end));assertThrows(RuntimeException.class,()->ComparisonEvidenceOptions.select(List.of("SH600030","SH600276"),"2Y",Map.of(),Map.of(),end));var r=ComparisonEvidenceOptions.select(List.of("SH600030","SH600276"),"3M",Map.of(),Map.of(),end);assertFalse(r.available());assertNull(r.to());assertEquals("NO_COMPARISON_EVIDENCE",r.stocks().get(0).reason());}
 @Test void incompatibleCalendarsDisableOptions(){var end=LocalDate.parse("2026-10-09");var from=end.minusMonths(3);var a=evidence("SH600030",from,end);var b=evidence("SH600276",from,end);var dates=from.datesUntil(end.plusDays(1)).toList();a=new Evidence(a.evidenceId(),a.instrumentId(),a.rawVersionId(),a.rawContentHash(),a.provider(),a.basis(),a.from(),a.to(),a.calendarHash(),a.contentHash(),a.sourcePayloadHash(),a.capturedAt(),a.days(),dates.stream().map(d->new com.aistock.market.quotation.TradingDay(d,true)).toList());b=new Evidence(b.evidenceId(),b.instrumentId(),b.rawVersionId(),b.rawContentHash(),b.provider(),b.basis(),b.from(),b.to(),b.calendarHash(),b.contentHash(),b.sourcePayloadHash(),b.capturedAt(),b.days(),dates.stream().map(d->new com.aistock.market.quotation.TradingDay(d,!d.equals(end))).toList());var r=ComparisonEvidenceOptions.select(List.of("SH600030","SH600276"),"3M",Map.of("SH600030",List.of(a),"SH600276",List.of(b)),Map.of(),end);assertFalse(r.available());assertTrue(r.stocks().stream().allMatch(s->"CALENDAR_CONFLICT".equals(s.reason())));}
}
